                      ? {2'h0, |(_decoder_1_io_rs1_need[1:0] & io_ex1_rd_0_when[3:2])}
                      : 3'h0;
  wire [2:0]  lane1Rs2Delay =
    rawRs2 & rawRs2Supported
      ? 3'h0
      : io_issue_laneValid[1] & _decoder_1_io_rs2_ren & io_issue_rd_1_wen
        & (|io_issue_rd_1_addr) & io_issue_rd_1_addr == _decoder_1_io_rs2_addr
          ? ((_decoder_1_io_rs2_need[2:0] & io_issue_rd_1_when[3:1]) == 3'h0
               ? 3'h0
               : (_decoder_1_io_rs2_need[1:0] & io_issue_rd_1_when[3:2]) == 2'h0
                   ? 3'h1
                   : 3'h2)
          : io_issue_laneValid[0] & _decoder_1_io_rs2_ren & io_issue_rd_0_wen
            & (|io_issue_rd_0_addr) & io_issue_rd_0_addr == _decoder_1_io_rs2_addr
              ? ((_decoder_1_io_rs2_need[2:0] & io_issue_rd_0_when[3:1]) == 3'h0
                   ? 3'h0
                   : (_decoder_1_io_rs2_need[1:0] & io_issue_rd_0_when[3:2]) == 2'h0
                       ? 3'h1
                       : 3'h2)
              : io_ex1_laneValid[1] & _decoder_1_io_rs2_ren & io_ex1_rd_1_wen
                & (|io_ex1_rd_1_addr) & io_ex1_rd_1_addr == _decoder_1_io_rs2_addr
                  ? {2'h0, |(_decoder_1_io_rs2_need[1:0] & io_ex1_rd_1_when[3:2])}
                  : io_ex1_laneValid[0] & _decoder_1_io_rs2_ren & io_ex1_rd_0_wen
                    & (|io_ex1_rd_0_addr) & io_ex1_rd_0_addr == _decoder_1_io_rs2_addr
                      ? {2'h0, |(_decoder_1_io_rs2_need[1:0] & io_ex1_rd_0_when[3:2])}
                      : 3'h0;
  wire [2:0]  lane1Delay = lane1Rs1Delay > lane1Rs2Delay ? lane1Rs1Delay : lane1Rs2Delay;
  wire        rejectSlot0Serial = hasPair & ~_decoder_0_io_slot0Pairable;
  wire        rejectSlot1Unsupported =
    hasPair & ~rejectSlot0Serial & ~_decoder_1_io_slot1Supported;
  wire        sharedMemoryConflict = _decoder_0_io_memory & _decoder_1_io_memory;
  wire        rejectSharedResource =
    hasPair & ~rejectSlot0Serial & ~rejectSlot1Unsupported & sharedMemoryConflict;
  wire        rejectWaw =
    hasPair & ~rejectSlot0Serial & ~rejectSlot1Unsupported & ~rejectSharedResource
    & wawBlocked;
  wire        rejectRaw =
    hasPair & ~rejectSlot0Serial & ~rejectSlot1Unsupported & ~rejectSharedResource
    & ~rejectWaw & rawBlocked;
  wire        _wawOpportunity_T = hasPair & _decoder_0_io_slot0Pairable;
  wire        pair =
    _wawOpportunity_T & _decoder_1_io_slot1Supported & ~sharedMemoryConflict & ~wawBlocked
    & ~rawBlocked & lane1Delay <= lane0Delay;
  wire [1:0]  selectedMask = io_in_valid & io_in_bits_laneValid[0] ? {pair, 1'h1} : 2'h0;
  wire        io_out_bits_lane_1_flat_rs1_0 =
    pair & rawRs1 & _decoder_0_io_ordinaryAlu & slot1FlatConsumer;
  wire        io_out_bits_lane_1_flat_rs2_0 =
    pair & rawRs2 & _decoder_0_io_ordinaryAlu & flatRs2Allowed;
  wire        _pairDecision_T = io_out_ready & (|selectedMask);
  wire        pairDecision = _pairDecision_T & hasPair;
  wire        io_pairSuccess_0 = pairDecision & pair;
  wire        io_rejectSlot0Serial_0 = pairDecision & rejectSlot0Serial;
  wire        io_rejectSlot1Unsupported_0 = pairDecision & rejectSlot1Unsupported;
  wire        io_rejectSharedResource_0 = pairDecision & rejectSharedResource;
  wire        io_rejectWaw_0 = pairDecision & rejectWaw;
  wire        io_rejectRaw_0 = pairDecision & rejectRaw;
  wire        io_rejectSlot1Late_0 =
    pairDecision & ~rejectSlot0Serial & ~rejectSlot1Unsupported & ~rejectSharedResource
    & ~rejectWaw & ~rejectRaw & lane1Delay > lane0Delay;
  wire        wawOpportunity =
    _wawOpportunity_T & _decoder_1_io_slot1Supported & ~sharedMemoryConflict & waw;
  wire        _wawMulRaw_T = wawOpportunity & sameGroupRaw;
  wire        io_wawOnly_0 = pairDecision & wawOpportunity & ~sameGroupRaw;
  wire        io_wawFlatRaw_0 =
    pairDecision & _wawMulRaw_T & _decoder_0_io_ordinaryAlu
    & (~rawRs1 | slot1FlatConsumer) & (~rawRs2 | flatRs2Allowed);
  wire        io_wawLoadRaw_0 =
    pairDecision & _wawMulRaw_T & _decoder_0_io_memory & ~_decoder_0_io_out_bits_mem_wen;
  wire        io_wawMulRaw_0 = pairDecision & _wawMulRaw_T & _decoder_0_io_multiply;
  `ifndef SYNTHESIS
    wire       _GEN = selectedMask == 2'h1;
    wire       _GEN_0 = pairDecision & ~reset;
    wire       _GEN_1 = _pairDecision_T & selectedMask[1];
    wire       _GEN_2 = _GEN_1 & ~reset;
    wire [2:0] _GEN_3 =
      {1'h0, {1'h0, io_wawMulRaw_0} + {1'h0, io_wawLoadRaw_0}}
      + {1'h0, {1'h0, io_wawFlatRaw_0} + {1'h0, io_wawOnly_0}};
    always @(posedge clock) begin
      if (~reset
          & ~(~io_in_valid | io_in_bits_laneValid == 2'h0 | io_in_bits_laneValid == 2'h1
              | (&io_in_bits_laneValid))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: decode input mask must be a contiguous oldest prefix\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset
          & ~(~(|selectedMask) | selectedMask == 2'h0 | _GEN | (&selectedMask))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: decode output mask must be a contiguous oldest prefix\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (_GEN_0
          & {1'h0,
             {1'h0, io_rejectSlot1Late_0} + {1'h0, io_rejectRaw_0}
               + {1'h0, io_rejectWaw_0}}
          + {1'h0,
             {1'h0, io_rejectSharedResource_0} + {1'h0, io_rejectSlot1Unsupported_0}}
          + {1'h0,
             {1'h0, io_rejectSlot0Serial_0} + {1'h0, io_pairSuccess_0}} != 3'h1) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: each pair opportunity must have exactly one outcome\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (_GEN_0 & (|(_GEN_3[2:1]))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: WAW detail classes must not overlap\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (pairDecision & _decoder_0_io_slot0Pairable & _decoder_1_io_slot1Supported
          & _decoder_0_io_ordinaryAlu & _decoder_1_io_controlFlow & sameGroupRaw & ~reset
          & ~(~pair & _GEN)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: an ALU0-dependent slot-1 branch must serialize\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (_GEN_2 & ~_decoder_1_io_slot1Supported) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: slot 1 received an unsupported instruction class\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (_GEN_2 & ~(~waw | wawSafe)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: same-group WAW must be commit-safe\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (_GEN_2 & ~(~sameGroupRaw | ~unforwardableRaw)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: same-group RAW must have an explicit flat path\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (_GEN_1 & _decoder_1_io_controlFlow & ~reset
          & ~(~io_out_bits_lane_1_flat_rs1_0 & ~io_out_bits_lane_1_flat_rs2_0)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: slot-1 control flow must not use the ALU0 flat path\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (_GEN_2 & sharedMemoryConflict) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: a group may receive at most one shared memory grant\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  IDU decoder_0 (
    .io_in_bits_pc                        (io_in_bits_lane_0_pc),
    .io_in_bits_inst                      (io_in_bits_lane_0_inst),
    .io_in_bits_snpc                      (io_in_bits_lane_0_snpc),
    .io_in_bits_predicted_pc              (io_in_bits_lane_0_predicted_pc),
    .io_in_bits_predicted_taken           (io_in_bits_lane_0_predicted_taken),
    .io_in_bits_tage_meta_valid           (io_in_bits_lane_0_tage_meta_valid),
    .io_in_bits_tage_meta_bits            (io_in_bits_lane_0_tage_meta_bits),
    .io_in_bits_loop_meta_valid           (io_in_bits_lane_0_loop_meta_valid),
    .io_in_bits_loop_meta_candidate       (io_in_bits_lane_0_loop_meta_candidate),
    .io_in_bits_loop_meta_prediction      (io_in_bits_lane_0_loop_meta_prediction),
    .io_in_bits_loop_meta_basePrediction  (io_in_bits_lane_0_loop_meta_basePrediction),
    .io_out_bits_predicted_pc             (io_out_bits_lane_0_predicted_pc),
    .io_out_bits_predicted_taken          (io_out_bits_lane_0_predicted_taken),
    .io_out_bits_tage_meta_valid          (io_out_bits_lane_0_tage_meta_valid),
    .io_out_bits_tage_meta_bits           (io_out_bits_lane_0_tage_meta_bits),
    .io_out_bits_loop_meta_valid          (io_out_bits_lane_0_loop_meta_valid),
    .io_out_bits_loop_meta_candidate      (io_out_bits_lane_0_loop_meta_candidate),
