    .io_out_bits_loop_meta_basePrediction (io_out_bits_lane_0_loop_meta_basePrediction),
    .io_out_bits_alu_ctrl                 (io_out_bits_lane_0_alu_ctrl),
    .io_out_bits_bru_ctrl                 (io_out_bits_lane_0_bru_ctrl),
    .io_out_bits_mdu_ctrl                 (io_out_bits_lane_0_mdu_ctrl),
    .io_out_bits_csr_ctrl                 (io_out_bits_lane_0_csr_ctrl),
    .io_out_bits_csr_mask                 (io_out_bits_lane_0_csr_mask),
    .io_out_bits_jump                     (io_out_bits_lane_0_jump),
    .io_out_bits_ras_push                 (io_out_bits_lane_0_ras_push),
    .io_out_bits_ras_pop                  (io_out_bits_lane_0_ras_pop),
    .io_out_bits_snpc                     (io_out_bits_lane_0_snpc),
    .io_out_bits_ALU_operand1             (io_out_bits_lane_0_ALU_operand1),
    .io_out_bits_ALU_operand2             (io_out_bits_lane_0_ALU_operand2),
    .io_out_bits_imm                      (io_out_bits_lane_0_imm),
    .io_out_bits_rs1_addr                 (io_out_bits_lane_0_rs1_addr),
    .io_out_bits_rs2_addr                 (io_out_bits_lane_0_rs2_addr),
    .io_out_bits_rs1_need                 (io_out_bits_lane_0_rs1_need),
    .io_out_bits_rs2_need                 (io_out_bits_lane_0_rs2_need),
    .io_out_bits_when                     (io_out_bits_lane_0_when),
    .io_out_bits_pc                       (io_out_bits_lane_0_pc),
    .io_out_bits_rd_addr                  (_decoder_0_io_out_bits_rd_addr),
    .io_out_bits_rd_wen                   (_decoder_0_io_out_bits_rd_wen),
    .io_out_bits_L_sign                   (io_out_bits_lane_0_L_sign),
    .io_out_bits_mem_wen                  (_decoder_0_io_out_bits_mem_wen),
    .io_out_bits_mem_bytes                (io_out_bits_lane_0_mem_bytes),
    .io_out_bits_envir                    (io_out_bits_lane_0_envir),
    .io_rs1_ren                           (_decoder_0_io_rs1_ren),
    .io_rs1_addr                          (_decoder_0_io_rs1_addr),
    .io_rs1_need                          (_decoder_0_io_rs1_need),
    .io_rs2_ren                           (_decoder_0_io_rs2_ren),
    .io_rs2_addr                          (_decoder_0_io_rs2_addr),
    .io_rs2_need                          (_decoder_0_io_rs2_need),
    .io_ordinaryAlu                       (_decoder_0_io_ordinaryAlu),
    .io_controlFlow                       (/* unused */),
    .io_memory                            (_decoder_0_io_memory),
    .io_multiply                          (_decoder_0_io_multiply),
    .io_slot1Supported                    (/* unused */),
    .io_slot0Pairable                     (_decoder_0_io_slot0Pairable)
