                   : io_ex2_rd_1_producerType)
              : hit_26
                  ? (~(|io_ex2_rd_0_producerType) & io_ex2_rd_0_when == 5'h3
                       ? 2'h3
                       : io_ex2_rd_0_producerType)
                  : hit_25
                      ? (~(|io_ex3_rd_1_producerType) & io_ex3_rd_1_when == 5'h3
                           ? 2'h3
                           : io_ex3_rd_1_producerType)
                      : hit_24
                          ? (~(|io_ex3_rd_0_producerType) & io_ex3_rd_0_when == 5'h3
                               ? 2'h3
                               : io_ex3_rd_0_producerType)
                          : hit_23
                              ? (~(|io_ex4_rd_1_producerType) & io_ex4_rd_1_when == 5'h3
                                   ? 2'h3
                                   : io_ex4_rd_1_producerType)
                              : hit_22
                                  ? (~(|io_ex4_rd_0_producerType)
                                     & io_ex4_rd_0_when == 5'h3
                                       ? 2'h3
                                       : io_ex4_rd_0_producerType)
                                  : hit_21
                                      ? (~(|io_wb_rd_1_producerType)
                                         & io_wb_rd_1_when == 5'h3
                                           ? 2'h3
                                           : io_wb_rd_1_producerType)
                                      : hit_20
                                          ? (~(|io_wb_rd_0_producerType)
                                             & io_wb_rd_0_when == 5'h3
                                               ? 2'h3
                                               : io_wb_rd_0_producerType)
                                          : 2'h0;
  assign io_operandProducerType_3 =
    hit_39
      ? (~(|io_ex1_rd_1_producerType) & io_ex1_rd_1_when == 5'h3
           ? 2'h3
           : io_ex1_rd_1_producerType)
      : hit_38
          ? (~(|io_ex1_rd_0_producerType) & io_ex1_rd_0_when == 5'h3
               ? 2'h3
               : io_ex1_rd_0_producerType)
          : hit_37
              ? (~(|io_ex2_rd_1_producerType) & io_ex2_rd_1_when == 5'h3
                   ? 2'h3
                   : io_ex2_rd_1_producerType)
              : hit_36
                  ? (~(|io_ex2_rd_0_producerType) & io_ex2_rd_0_when == 5'h3
                       ? 2'h3
                       : io_ex2_rd_0_producerType)
                  : hit_35
                      ? (~(|io_ex3_rd_1_producerType) & io_ex3_rd_1_when == 5'h3
                           ? 2'h3
                           : io_ex3_rd_1_producerType)
                      : hit_34
                          ? (~(|io_ex3_rd_0_producerType) & io_ex3_rd_0_when == 5'h3
                               ? 2'h3
                               : io_ex3_rd_0_producerType)
                          : hit_33
                              ? (~(|io_ex4_rd_1_producerType) & io_ex4_rd_1_when == 5'h3
                                   ? 2'h3
                                   : io_ex4_rd_1_producerType)
                              : hit_32
                                  ? (~(|io_ex4_rd_0_producerType)
                                     & io_ex4_rd_0_when == 5'h3
                                       ? 2'h3
                                       : io_ex4_rd_0_producerType)
                                  : hit_31
                                      ? (~(|io_wb_rd_1_producerType)
                                         & io_wb_rd_1_when == 5'h3
                                           ? 2'h3
                                           : io_wb_rd_1_producerType)
                                      : hit_30
                                          ? (~(|io_wb_rd_0_producerType)
                                             & io_wb_rd_0_when == 5'h3
                                               ? 2'h3
                                               : io_wb_rd_0_producerType)
                                          : 2'h0;
  assign io_operandConsumerType_0 =
    isControl ? 2'h1 : {~(&io_in_bits_lane_0_mem_bytes), 1'h0};
  assign io_operandConsumerType_1 =
    isControl ? 2'h1 : {2{~(&io_in_bits_lane_0_mem_bytes) & io_in_bits_lane_0_mem_wen}};
  assign io_operandConsumerType_2 =
    isControl_1 ? 2'h1 : {~(&io_in_bits_lane_1_mem_bytes), 1'h0};
  assign io_operandConsumerType_3 =
    isControl_1 ? 2'h1 : {2{~(&io_in_bits_lane_1_mem_bytes) & io_in_bits_lane_1_mem_wen}};
  assign io_operandPc_0 = io_in_bits_lane_0_pc;
  assign io_operandPc_1 = io_in_bits_lane_1_pc;
endmodule

module ALU(
  input  [12:0] io_alu_ctrl,
  input  [31:0] io_din1,
                io_din2,
  output [31:0] io_dout
);

  wire [62:0] _dout_T_37 = {31'h0, io_din1} << io_din2[4:0];
  wire [31:0] _GEN = {27'h0, io_din2[4:0]};
  wire [31:0] _dout_T_54 =
    {32{io_alu_ctrl[0]}} & io_din1 | {32{io_alu_ctrl[1]}} & io_din2 | {32{io_alu_ctrl[2]}}
    & io_din1 + io_din2 | {32{io_alu_ctrl[3]}} & io_din1 - io_din2 | {32{io_alu_ctrl[4]}}
    & (io_din1 ^ io_din2) | {32{io_alu_ctrl[5]}} & (io_din1 | io_din2)
    | {32{io_alu_ctrl[6]}} & io_din1 & io_din2 | {32{io_alu_ctrl[7]}} & _dout_T_37[31:0]
    | {32{io_alu_ctrl[8]}} & io_din1 >> _GEN | {32{io_alu_ctrl[9]}}
    & $signed($signed(io_din1) >>> _GEN);
  assign io_dout =
    {_dout_T_54[31:1],
     _dout_T_54[0] | io_alu_ctrl[10] & $signed(io_din1) < $signed(io_din2)
       | io_alu_ctrl[11] & io_din1 < io_din2};
endmodule

module BRU(
  input  [8:0]  io_bru_ctrl,
  input  [31:0] io_imm,
                io_snpc,
                io_pc,
                io_rs1_val,
                io_rs2_val,
  output        io_redirect,
  output [31:0] io_target_pc
);

  wire _redirect_T = io_bru_ctrl[2:0] == 3'h1;
  wire _redirect_T_2 = io_bru_ctrl[2:0] == 3'h2;
  wire _redirect_T_4 = io_bru_ctrl[2:0] == 3'h4;
  assign io_redirect =
    _redirect_T_4 | _redirect_T_2 | _redirect_T
    & (io_bru_ctrl[8:3] == 6'h20
         ? io_rs1_val >= io_rs2_val
         : io_bru_ctrl[8:3] == 6'h8
             ? io_rs1_val < io_rs2_val
             : io_bru_ctrl[8:3] == 6'h10
                 ? $signed(io_rs1_val) >= $signed(io_rs2_val)
                 : io_bru_ctrl[8:3] == 6'h4
                     ? $signed(io_rs1_val) < $signed(io_rs2_val)
                     : io_bru_ctrl[8:3] == 6'h2
                         ? io_rs1_val != io_rs2_val
                         : io_bru_ctrl[8:3] == 6'h1 & io_rs1_val == io_rs2_val);
  assign io_target_pc =
    _redirect_T_4
      ? io_imm + io_rs1_val & 32'hFFFFFFFE
      : _redirect_T_2 | _redirect_T ? io_imm + io_pc : io_snpc;
endmodule

// external module Multiplier

// external module MultiplierInputCapture

module MUL(
  input         clock,
                reset,
  input  [4:0]  io_mdu_ctrl,
  input         io_enable,
  input  [31:0] io_din1,
                io_din2,
  output [63:0] io_dout
);

  wire [32:0] _capture_A_CAPTURE;
  wire [32:0] _capture_B_CAPTURE;
  Multiplier Mult (
    .CLK (clock),
    .CE  (io_enable),
    .A   (_capture_A_CAPTURE),
    .B   (_capture_B_CAPTURE),
    .P   (io_dout)
  );
  MultiplierInputCapture capture (
    .CLK       (clock),
    .reset     (reset),
    .CE        (io_enable),
    .A         ({io_mdu_ctrl[4] & io_din1[31], io_din1}),
    .B         ({io_mdu_ctrl[3] & io_din2[31], io_din2}),
    .A_CAPTURE (_capture_A_CAPTURE),
    .B_CAPTURE (_capture_B_CAPTURE)
  );
endmodule

// external module Divider

module DIV(
  input         clock,
                reset,
  input  [4:0]  io_mdu_ctrl,
  input         io_valid,
  input  [31:0] io_din1,
                io_din2,
  output [31:0] io_dout,
  output        io_stall,
                io_busy,
                io_done
);

  wire        _Div_s_axis_dividend_tready;
  wire        _Div_s_axis_divisor_tready;
  wire [63:0] _Div_m_axis_dout_tdata;
  wire        _Div_m_axis_dout_tvalid;
  reg  [5:0]  div_counter;
  wire        div_terminal = div_counter == 6'h23;
  reg         div_done_reg;
  wire        div_running = (|div_counter) & div_counter != 6'h23;
  reg         div_pos_reg;
  reg         div_by_zero_reg;
  reg  [31:0] div_dividend_reg;
  reg         div_quotient_neg_reg;
  reg         div_remainder_neg_reg;
  reg  [31:0] div_result_reg;
  wire        div_request = io_valid & io_mdu_ctrl[1:0] == 2'h2;
  reg         div_request_q;
  wire        div_start =
    div_request & ~(|div_counter) & (~div_done_reg | div_request & ~div_request_q);
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (div_start & (|io_din2) & ~reset
          & ~(_Div_s_axis_dividend_tready & _Div_s_axis_divisor_tready)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: fixed-latency divider must accept both operands in its idle cycle\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (div_terminal & ~div_by_zero_reg & ~reset & ~_Div_m_axis_dout_tvalid) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: Divider IP output latency does not match the 35-cycle controller\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  always @(posedge clock) begin
    if (reset) begin
      div_counter <= 6'h0;
      div_done_reg <= 1'h0;
      div_request_q <= 1'h0;
    end
    else begin
      if (div_start)
        div_counter <= 6'h1;
      else if (div_running)
        div_counter <= div_counter + 6'h1;
      else if (div_terminal)
        div_counter <= 6'h0;
      div_done_reg <= ~div_start & (div_terminal | div_done_reg);
      div_request_q <= div_request;
    end
    if (div_start) begin
      div_pos_reg <= io_mdu_ctrl[2];
      div_by_zero_reg <= ~(|io_din2);
      div_dividend_reg <= io_din1;
      div_quotient_neg_reg <=
        (&(io_mdu_ctrl[4:3])) & (io_din1[31] ^ io_din2[31]) & (|io_din2);
      div_remainder_neg_reg <= (&(io_mdu_ctrl[4:3])) & io_din1[31];
    end
    if (div_terminal)
      div_result_reg <=
        div_by_zero_reg
          ? (div_pos_reg ? 32'hFFFFFFFF : div_dividend_reg)
          : div_pos_reg
              ? (div_quotient_neg_reg
                   ? 32'h0 - _Div_m_axis_dout_tdata[63:32]
                   : _Div_m_axis_dout_tdata[63:32])
              : div_remainder_neg_reg
                  ? 32'h0 - _Div_m_axis_dout_tdata[31:0]
                  : _Div_m_axis_dout_tdata[31:0];
  end // always @(posedge)
  Divider Div (
    .aclk                   (clock),
    .s_axis_dividend_tdata
      ((&(io_mdu_ctrl[4:3])) & io_din1[31] ? 32'h0 - io_din1 : io_din1),
    .s_axis_dividend_tready (_Div_s_axis_dividend_tready),
    .s_axis_dividend_tvalid (div_start & (|io_din2)),
    .s_axis_divisor_tdata
      ((&(io_mdu_ctrl[4:3])) & io_din2[31] ? 32'h0 - io_din2 : io_din2),
    .s_axis_divisor_tready  (_Div_s_axis_divisor_tready),
    .s_axis_divisor_tvalid  (div_start & (|io_din2)),
    .m_axis_dout_tdata      (_Div_m_axis_dout_tdata),
    .m_axis_dout_tvalid     (_Div_m_axis_dout_tvalid)
  );
  assign io_dout = div_result_reg;
  assign io_stall = div_request & div_running;
  assign io_busy = |div_counter;
  assign io_done = div_done_reg;
endmodule


