module CSR(
  input         clock,
                reset,
  input  [9:0]  io_read_mask,
  input         io_valid,
  input  [2:0]  io_ctrl,
  input  [31:0] io_wdata,
  input  [9:0]  io_mask,
  input         io_ecall,
                io_mret,
  input  [31:0] io_trap_pc,
  input         io_timer_irq,
                io_interrupt_take,
  input  [31:0] io_interrupt_pc,
  output [31:0] io_rdata,
                io_mtvec,
                io_mepc,
  output        io_interrupt_pending
);

  reg  [31:0] csrRegs_0_2;
  reg  [31:0] csrRegs_1_2;
  reg  [31:0] csrRegs_2_2;
  reg  [31:0] csrRegs_3_2;
  reg  [31:0] csrRegs_4_2;
  reg  [31:0] csrRegs_5_2;
  reg  [31:0] csrRegs_6_2;
  reg  [31:0] csrRegs_7_2;
  reg  [31:0] csrRegs_8_2;
  wire [63:0] _mcycle_next_T_1 = {csrRegs_8_2, csrRegs_7_2} + 64'h1;
  wire        _write_old_data_T = io_mask == 10'h1;
  wire        _write_old_data_T_2 = io_mask == 10'h40;
  wire        _write_old_data_T_4 = io_mask == 10'h80;
  wire        _write_old_data_T_6 = io_mask == 10'h2;
  wire        _write_old_data_T_8 = io_mask == 10'h4;
  wire        _write_old_data_T_10 = io_mask == 10'h8;
  wire        _write_old_data_T_12 = io_mask == 10'h10;
  wire        _write_old_data_T_14 = io_mask == 10'h100;
  wire        _write_old_data_T_16 = io_mask == 10'h200;
  wire [31:0] write_old_data =
    _write_old_data_T_16
      ? csrRegs_8_2
      : _write_old_data_T_14
          ? csrRegs_7_2
          : _write_old_data_T_12
              ? csrRegs_6_2
              : _write_old_data_T_10
                  ? csrRegs_5_2
                  : _write_old_data_T_8
                      ? csrRegs_4_2
                      : _write_old_data_T_6
                          ? csrRegs_3_2
                          : _write_old_data_T_4
                              ? csrRegs_2_2
                              : _write_old_data_T_2
                                  ? csrRegs_1_2
                                  : _write_old_data_T ? csrRegs_0_2 : 32'h0;
  wire [31:0] csr_wdata =
    io_ctrl == 3'h3
      ? write_old_data & ~io_wdata
      : {32{io_ctrl == 3'h2}} & write_old_data | io_wdata;
  wire        do_write =
    io_valid & (|io_ctrl) & (|io_mask) & (|{io_ctrl == 3'h1, io_wdata});
  wire        _GEN = io_interrupt_take | io_ecall | io_mret;
  wire        _GEN_0 = do_write & _write_old_data_T_16;
  always @(posedge clock) begin
    if (reset) begin
      csrRegs_0_2 <= 32'h1800;
      csrRegs_1_2 <= 32'h0;
      csrRegs_2_2 <= 32'h0;
      csrRegs_3_2 <= 32'h0;
      csrRegs_4_2 <= 32'h0;
      csrRegs_5_2 <= 32'h0;
      csrRegs_6_2 <= 32'h0;
      csrRegs_7_2 <= 32'h0;
      csrRegs_8_2 <= 32'h0;
    end
    else begin
      if (io_interrupt_take) begin
        csrRegs_0_2 <=
          {csrRegs_0_2[31:8], csrRegs_0_2[3], csrRegs_0_2[6:4], 1'h0, csrRegs_0_2[2:0]};
        csrRegs_2_2 <= csrRegs_2_2 & 32'hFFFFFF7F;
        csrRegs_3_2 <= io_interrupt_pc;
        csrRegs_5_2 <= 32'h80000007;
      end
      else begin
        if (io_ecall) begin
          csrRegs_0_2 <=
            {csrRegs_0_2[31:8], csrRegs_0_2[3], csrRegs_0_2[6:4], 1'h0, csrRegs_0_2[2:0]};
          csrRegs_3_2 <= io_trap_pc;
          csrRegs_5_2 <= 32'hB;
        end
        else begin
          if (io_mret)
            csrRegs_0_2 <=
              {csrRegs_0_2[31:8],
               1'h1,
               csrRegs_0_2[6:4],
               csrRegs_0_2[7],
               csrRegs_0_2[2:0]};
          else if (do_write & _write_old_data_T)
            csrRegs_0_2 <= csr_wdata;
          if (io_mret | ~(do_write & _write_old_data_T_6)) begin
          end
          else
            csrRegs_3_2 <= csr_wdata;
          if (io_mret | ~(do_write & _write_old_data_T_10)) begin
          end
          else
            csrRegs_5_2 <= csr_wdata;
        end
        if (io_timer_irq)
          csrRegs_2_2 <= csrRegs_2_2 | 32'h80;
        else if (do_write & _write_old_data_T_4)
          csrRegs_2_2 <= csr_wdata;
      end
      if (_GEN | ~(do_write & _write_old_data_T_2)) begin
      end
      else
        csrRegs_1_2 <= csr_wdata;
      if (_GEN | ~(do_write & _write_old_data_T_8)) begin
      end
      else
        csrRegs_4_2 <= csr_wdata;
      if (_GEN | ~(do_write & _write_old_data_T_12)) begin
      end
      else
        csrRegs_6_2 <= csr_wdata;
      if (do_write & _write_old_data_T_14)
        csrRegs_7_2 <= csr_wdata;
      else begin
        if (~_GEN_0)
          csrRegs_7_2 <= _mcycle_next_T_1[31:0];
        csrRegs_8_2 <= _GEN_0 ? csr_wdata : _mcycle_next_T_1[63:32];
      end
    end
  end // always @(posedge)
  assign io_rdata =
    io_read_mask == 10'h200
      ? csrRegs_8_2
      : io_read_mask == 10'h100
          ? csrRegs_7_2
          : io_read_mask == 10'h10
              ? csrRegs_6_2
              : io_read_mask == 10'h8
                  ? csrRegs_5_2
                  : io_read_mask == 10'h4
                      ? csrRegs_4_2
                      : io_read_mask == 10'h2
                          ? csrRegs_3_2
                          : io_read_mask == 10'h80
                              ? csrRegs_2_2
                              : io_read_mask == 10'h40
                                  ? csrRegs_1_2
                                  : io_read_mask == 10'h1 ? csrRegs_0_2 : 32'h0;
  assign io_mtvec = csrRegs_4_2;
  assign io_mepc = csrRegs_3_2;
  assign io_interrupt_pending = csrRegs_0_2[3] & csrRegs_1_2[7] & csrRegs_2_2[7];
endmodule

