    {{32'h0}, {data_0}, {{2{data_0[15:0]}}}, {{2{{2{data_0[7:0]}}}}}};
  wire [3:0][3:0]  _GEN_1 =
    {{4'h0}, {4'hF}, {addr_1[1] ? 4'hC : 4'h3}, {4'h1 << addr_1[1:0]}};
  wire [3:0]       entryMask_1 =
    io_lookup_valid & (|(count[2:1])) & addr_1[31:2] == io_lookup_addr[31:2]
