  wire [3:0][31:0] _GEN_2 =
    {{32'h0}, {data_1}, {{2{data_1[15:0]}}}, {{2{{2{data_1[7:0]}}}}}};
  wire [3:0][3:0]  _GEN_3 =
    {{4'h0}, {4'hF}, {addr_2[1] ? 4'hC : 4'h3}, {4'h1 << addr_2[1:0]}};
  wire [3:0]       entryMask_2 =
    io_lookup_valid & count > 3'h2 & addr_2[31:2] == io_lookup_addr[31:2]
      ? _GEN_3[bytes_2]
      : 4'h0;
  wire [31:0]      bitMask_2 =
    {{8{entryMask_2[3]}}, {8{entryMask_2[2]}}, {8{entryMask_2[1]}}, {8{entryMask_2[0]}}};
  wire [3:0][31:0] _GEN_4 =
    {{32'h0}, {data_2}, {{2{data_2[15:0]}}}, {{2{{2{data_2[7:0]}}}}}};
  wire [3:0][3:0]  _GEN_5 =
    {{4'h0}, {4'hF}, {addr_3[1] ? 4'hC : 4'h3}, {4'h1 << addr_3[1:0]}};
  wire [3:0]       entryMask_3 =
    io_lookup_valid & count[2] & addr_3[31:2] == io_lookup_addr[31:2]
      ? _GEN_5[bytes_3]
