      addr_0 <= io_enq_bits_addr;
      data_0 <= io_enq_bits_data;
      bytes_0 <= io_enq_bits_bytes;
    end
    else if (deq) begin
      addr_0 <= addr_1;
      data_0 <= data_1;
      bytes_0 <= bytes_1;
    end
    if (enq & enqIndex == 2'h1) begin
      addr_1 <= io_enq_bits_addr;
      data_1 <= io_enq_bits_data;
      bytes_1 <= io_enq_bits_bytes;
    end
    else if (deq) begin
      addr_1 <= addr_2;
      data_1 <= data_2;
      bytes_1 <= bytes_2;
    end
    if (enq & enqIndex == 2'h2) begin
      addr_2 <= io_enq_bits_addr;
      data_2 <= io_enq_bits_data;
      bytes_2 <= io_enq_bits_bytes;
    end
    else if (deq) begin
      addr_2 <= addr_3;
      data_2 <= data_3;
      bytes_2 <= bytes_3;
