  assign io_deq_valid = ~io_empty_0;
  assign io_deq_bits_addr = addr_0;
  assign io_deq_bits_data = data_0;
  assign io_deq_bits_bytes = bytes_0;
  assign io_deq_bits_cache_hit = _cacheMeta_ext_R0_data[32];
