// external module WBU_DPIC

module WBU(
  input         clock,
  output        io_valid,
  input         io_in_valid,
  input  [31:0] io_in_bits_addr,
  input  [1:0]  io_in_bits_mem_bytes,
  input         io_in_bits_mem_wen,
  input  [4:0]  io_in_bits_when,
                io_in_bits_mdu_ctrl,
  input         io_in_bits_rd_wen,
  input  [4:0]  io_in_bits_rd_addr,
  input  [31:0] io_in_bits_rd_data,
  input  [63:0] io_mul_out,
  input  [31:0] io_div_out,
  input         io_div_done,
                io_backend_stall,
  output        io_long_stall,
                io_div_stall,
                io_gpr_wen,
  output [4:0]  io_gpr_addr,
  output [31:0] io_gpr_data,
  output        io_rd_wen,
  output [4:0]  io_rd_addr,
                io_rd_when,
  output [1:0]  io_rd_producerType
);

  wire _div_stall_T = io_in_bits_mdu_ctrl[1:0] == 2'h2;
  wire div_stall = io_in_valid & _div_stall_T & ~io_div_done;
  wire _DPIC_io_read_T_4 = io_in_bits_mem_bytes != 2'h3;
  WBU_DPIC DPIC (
    .clk   (clock),
    .read  (io_in_valid & ~io_backend_stall & ~io_in_bits_mem_wen & _DPIC_io_read_T_4),
    .write (io_in_valid & ~io_backend_stall & io_in_bits_mem_wen),
    .addr  (io_in_bits_addr)
  );
  assign io_valid = io_in_valid & ~div_stall & ~io_backend_stall;
  assign io_long_stall = div_stall;
  assign io_div_stall = div_stall;
  assign io_gpr_wen = io_in_bits_rd_wen;
  assign io_gpr_addr = io_in_bits_rd_addr;
  assign io_gpr_data =
    _div_stall_T
      ? io_div_out
      : io_in_bits_mdu_ctrl[1:0] == 2'h1
          ? (io_in_bits_mdu_ctrl[2] ? io_mul_out[63:32] : io_mul_out[31:0])
          : io_in_bits_rd_data;
  assign io_rd_wen = io_in_bits_rd_wen;
  assign io_rd_addr = io_in_bits_rd_addr;
  assign io_rd_when = io_in_bits_when;
  assign io_rd_producerType =
    _DPIC_io_read_T_4 & ~io_in_bits_mem_wen ? 2'h1 : {|io_in_bits_mdu_ctrl, 1'h0};
endmodule

module GroupWBU(
