  output        io_gpr_1_wen,
  output [4:0]  io_gpr_1_addr,
  output [31:0] io_gpr_1_data,
  output [1:0]  io_producer_laneValid,
  output        io_producer_rd_0_wen,
  output [4:0]  io_producer_rd_0_addr,
                io_producer_rd_0_when,
  output [1:0]  io_producer_rd_0_producerType,
  output        io_producer_rd_1_wen,
  output [4:0]  io_producer_rd_1_addr,
                io_producer_rd_1_when,
  output [1:0]  io_producer_rd_1_producerType,
  output [31:0] io_producer_value_0,
                io_producer_value_1,
                io_pc_0,
                io_pc_1,
                io_pcNext_0,
                io_pcNext_1,
  output [2:0]  io_envir_0,
                io_envir_1
