  wire        _lane0_io_valid;
  wire        _lane0_io_long_stall;
  wire [31:0] _lane0_io_gpr_data;
  wire        _lane0_io_rd_wen;
  wire [1:0]  rawRetireMask = _lane0_io_valid ? io_in_bits_laneValid : 2'h0;
  wire [1:0]  rawProducerMask =
    io_in_valid & ~_lane0_io_long_stall ? io_in_bits_laneValid : 2'h0;
  wire        slot0KillsSlot1 = rawRetireMask[0] & (|io_in_bits_lane_0_envir);
  wire        producerSlot0KillsSlot1 = rawProducerMask[0] & (|io_in_bits_lane_0_envir);
  wire [1:0]  io_retireMask_0 = rawRetireMask & {~slot0KillsSlot1, 1'h1};
  wire        _producerSameGroupWaw_T_5 =
    io_in_bits_lane_0_rd_addr == io_in_bits_lane_1_rd_addr;
  wire        sameGroupWaw =
    (&io_retireMask_0) & io_in_bits_lane_0_rd_wen & io_in_bits_lane_1_rd_wen
    & (|io_in_bits_lane_0_rd_addr) & _producerSameGroupWaw_T_5;
  wire [1:0]  io_gprWriteMask_0 = io_retireMask_0 & {1'h1, ~sameGroupWaw};
  wire [1:0]  producerMask = rawProducerMask & {~producerSlot0KillsSlot1, 1'h1};
  wire        _sideData_T = io_in_bits_lane_1_mdu_ctrl[1:0] == 2'h1;
  wire [31:0] sideData =
    _sideData_T
      ? (io_in_bits_lane_1_mdu_ctrl[2] ? io_side_mul_out[63:32] : io_side_mul_out[31:0])
      : io_in_bits_lane_1_rd_data;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (~reset
          & ~(~io_in_valid | io_in_bits_laneValid == 2'h0 | io_in_bits_laneValid == 2'h1
              | (&io_in_bits_laneValid))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: writeback group mask must be a contiguous oldest prefix\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & ~(~(io_retireMask_0[1]) | io_retireMask_0[0])) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: slot 1 must never retire without slot 0\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & ~(~(producerMask[1]) | producerMask[0])) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: slot 1 must never forward without slot 0\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & ~(~_lane0_io_long_stall | producerMask == 2'h0)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: an unfinished long operation must not forward\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & ~(~slot0KillsSlot1 | ~(io_retireMask_0[1]))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: slot 1 must not retire after a slot 0 exception or return\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset
          & ~(~sameGroupWaw | ~(io_gprWriteMask_0[0]) & io_gprWriteMask_0[1])) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: a same-group WAW must commit only the younger physical write\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset
          & ~(~(io_retireMask_0[1]) | io_in_bits_lane_1_pc == io_in_bits_lane_0_pc
              + 32'h4)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: dual-retire instruction PCs must remain consecutive\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (io_in_valid & io_in_bits_laneValid[1] & ~reset
          & ~(io_in_bits_lane_1_mdu_ctrl[1:0] == 2'h0 | _sideData_T)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: slot 1 writeback only supports integer multiply\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  WBU lane0 (
    .clock                (clock),
    .io_valid             (_lane0_io_valid),
    .io_in_valid          (io_in_valid & io_in_bits_laneValid[0]),
    .io_in_bits_addr      (io_in_bits_lane_0_addr),
    .io_in_bits_mem_bytes (io_in_bits_lane_0_mem_bytes),
    .io_in_bits_mem_wen   (io_in_bits_lane_0_mem_wen),
    .io_in_bits_when      (io_in_bits_lane_0_when),
    .io_in_bits_mdu_ctrl  (io_in_bits_lane_0_mdu_ctrl),
    .io_in_bits_rd_wen    (io_in_bits_lane_0_rd_wen),
    .io_in_bits_rd_addr   (io_in_bits_lane_0_rd_addr),
    .io_in_bits_rd_data   (io_in_bits_lane_0_rd_data),
    .io_mul_out           (io_mul_out),
    .io_div_out           (io_div_out),
    .io_div_done          (io_div_done),
    .io_backend_stall     (io_backend_stall),
    .io_long_stall        (_lane0_io_long_stall),
    .io_div_stall         (io_div_stall),
    .io_gpr_wen           (io_gpr_0_wen),
    .io_gpr_addr          (io_gpr_0_addr),
    .io_gpr_data          (_lane0_io_gpr_data),
    .io_rd_wen            (_lane0_io_rd_wen),
    .io_rd_addr           (io_producer_rd_0_addr),
    .io_rd_when           (io_producer_rd_0_when),
    .io_rd_producerType   (io_producer_rd_0_producerType)
  );
  assign io_valid = |io_retireMask_0;
  assign io_retireMask = io_retireMask_0;
  assign io_gprWriteMask = io_gprWriteMask_0;
  assign io_long_stall = _lane0_io_long_stall;
  assign io_gpr_0_data = _lane0_io_gpr_data;
  assign io_gpr_1_wen = io_in_bits_lane_1_rd_wen;
  assign io_gpr_1_addr = io_in_bits_lane_1_rd_addr;
  assign io_gpr_1_data = sideData;
  assign io_producer_laneValid = producerMask;
  assign io_producer_rd_0_wen =
    _lane0_io_rd_wen & rawProducerMask[0]
    & ~((&producerMask) & io_in_bits_lane_0_rd_wen & io_in_bits_lane_1_rd_wen
        & (|io_in_bits_lane_0_rd_addr) & _producerSameGroupWaw_T_5);
  assign io_producer_rd_1_wen =
    io_in_bits_lane_1_rd_wen & rawProducerMask[1] & ~producerSlot0KillsSlot1;
  assign io_producer_rd_1_addr = io_in_bits_lane_1_rd_addr;
  assign io_producer_rd_1_when = io_in_bits_lane_1_when;
  assign io_producer_rd_1_producerType =
    io_in_bits_lane_1_mem_bytes != 2'h3 & ~io_in_bits_lane_1_mem_wen
      ? 2'h1
      : {|io_in_bits_lane_1_mdu_ctrl, 1'h0};
  assign io_producer_value_0 = _lane0_io_gpr_data;
  assign io_producer_value_1 = sideData;
  assign io_pc_0 = io_in_bits_lane_0_pc;
  assign io_pc_1 = io_in_bits_lane_1_pc;
  assign io_pcNext_0 = io_in_bits_lane_0_pc_next;
  assign io_pcNext_1 = io_in_bits_lane_1_pc_next;
  assign io_envir_0 = io_in_bits_lane_0_envir;
  assign io_envir_1 = io_in_bits_lane_1_envir;
endmodule

