    hzu_branch_resolve_predicted_pc <= io_ex1_branch_resolve_predicted_pc;
    hzu_branch_resolve_predicted_taken <= io_ex1_branch_resolve_predicted_taken;
    hzu_branch_resolve_is_branch <= io_ex1_branch_resolve_is_branch;
